            <div class="meta" aria-label="Image details">
              <div class="meta-row">
                <span>Collection</span>
                <span>Architecture</span>
              </div>
              <div class="meta-row">
                <span>Saved</span>
                <span>Today</span>
              </div>
              <div class="meta-row">
