  <dialog class="modal" id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
    <form class="modal-card" method="dialog">
      <div class="modal-icon" aria-hidden="true">!</div>
      <h2 id="dialog-title">Delete this image?</h2>
