      border-radius: var(--radius);
      box-shadow: 0 18px 36px rgba(0, 0, 0, 0.32);
    }

    .details {
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      gap: 2rem;
      padding: clamp(1.5rem, 4vw, 2.5rem);
    }

    .eyebrow {
      color: var(--primary);
      font-size: 0.78rem;
