    }

    .button:hover {
      transform: translateY(-1px);
    }

    .button-primary {
      background: var(--primary);
      box-shadow: 0 12px 24px rgba(37, 99, 235, 0.22);
      color: #ffffff;
    }

    .button-primary:hover {
      background: var(--primary-dark);
    }

    .button-danger {
      background: #fee2e2;
      color: var(--danger);
    }

    .button-danger:hover {
      background: #fecaca;
      color: var(--danger-dark);
    }

    .button-ghost {
      background: #eef2f7;
      color: var(--text);
    }

    .button-confirm {
      background: var(--danger);
      box-shadow: 0 12px 24px rgba(220, 38, 38, 0.22);
      color: #ffffff;
    }

    .button-confirm:hover {
      background: var(--danger-dark);
    }

    .modal {
      border: 0;
      border-radius: 28px;
      box-shadow: var(--shadow);
      color: var(--text);
      max-width: min(92vw, 460px);
      padding: 0;
      width: 100%;
    }

    .modal::backdrop {
      background: rgba(15, 23, 42, 0.62);
      backdrop-filter: blur(4px);
    }

    .modal-card {
      padding: 2rem;
    }

    .modal-icon {
      align-items: center;
      background: #fee2e2;
      border-radius: 18px;
      color: var(--danger);
      display: inline-flex;
      font-size: 1.5rem;
      font-weight: 900;
      height: 3.25rem;
      justify-content: center;
      margin-bottom: 1.25rem;
      width: 3.25rem;
    }

    .modal h2 {
      font-size: 1.6rem;
      letter-spacing: -0.035em;
      line-height: 1.1;
      margin: 0 0 0.75rem;
    }

    .modal p {
      color: var(--muted);
      line-height: 1.65;
      margin: 0 0 1.5rem;
    }

    .modal-actions {
      display: flex;
      flex-wrap: wrap-reverse;
      gap: 0.75rem;
      justify-content: flex-end;
    }

    .confirmation {
      color: #166534;
      font-weight: 800;
      min-height: 1.5rem;
      margin-top: 1rem;
    }

    @media (max-width: 820px) {
      body {
        padding: 1rem;
      }

      .preview-layout {
        grid-template-columns: 1fr;
      }

      .image-wrap {
        min-height: 340px;
      }
    }
  </style>
</head>
<body>
  <main class="page">
    <article class="preview-card" aria-labelledby="image-title">
      <div class="preview-layout">
        <div class="image-wrap">
          <img
            src="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1400&q=80"
            alt="A modern house beside a lake at golden hour"
          >
        </div>

        <section class="details">
          <div>
            <p class="eyebrow">Library preview</p>
            <h1 id="image-title">Lakeside Modern Retreat</h1>
            <p class="description">
              A saved inspiration image from your design library. Review the details below or remove it from your collection.
            </p>

            <div class="meta" aria-label="Image details">
              <div class="meta-row">
                <span>Collection</span>
                <span>Architecture</span>
              </div>
              <div class="meta-row">
                <span>Saved</span>
                <span>Today</span>
              </div>
              <div class="meta-row">
                <span>Resolution</span>
                <span>2800 x 1867</span>
              </div>
            </div>
          </div>

          <div>
            <div class="actions" aria-label="Image actions">
              <button class="button button-primary" type="button">Download</button>
              <button class="button button-danger trigger" type="button" aria-haspopup="dialog">
                Delete image
              </button>
            </div>
            <p class="confirmation" id="confirmation-message" aria-live="polite"></p>
          </div>
        </section>
      </div>
    </article>
  </main>

  <dialog class="modal" id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
    <form class="modal-card" method="dialog">
      <div class="modal-icon" aria-hidden="true">!</div>
      <h2 id="dialog-title">Delete this image?</h2>
      <p id="dialog-description">
        This will permanently remove "Lakeside Modern Retreat" from your library. This action cannot be undone.
      </p>
      <div class="modal-actions">
        <button class="button button-ghost" type="button" data-close-dialog>Cancel</button>
        <button class="button button-confirm" type="submit" value="confirm">Yes, delete image</button>
      </div>
    </form>
  </dialog>

  <script>
    const trigger = document.querySelector(".trigger");
    const dialog = document.querySelector("#delete-dialog");
    const closeButton = document.querySelector("[data-close-dialog]");
    const confirmationMessage = document.querySelector("#confirmation-message");

    trigger.addEventListener("click", () => {
      confirmationMessage.textContent = "";
      dialog.showModal();
    });

    closeButton.addEventListener("click", () => {
      dialog.close("cancel");
      trigger.focus();
    });

    dialog.addEventListener("close", () => {
      if (dialog.returnValue === "confirm") {
        confirmationMessage.textContent = "Image deleted from your library.";
        trigger.focus();
      }
    });
  </script>
</body>
</html>
